from collections import Counter, OrderedDict, defaultdict, deque
import heapq

def combination_sum3(k: int, n: int) -> list[list[int]]:
    out: list[list[int]] = []
    path: list[int] = []

    def dfs(start: int, remain: int) -> None:
        if len(path) == k:
            if remain == 0:
                out.append(path[:])
            return
        for value in range(start, 10):
            if value > remain:
                break
            path.append(value)
            dfs(value + 1, remain - value)
            path.pop()

    dfs(1, n)
    return out

